package com.onlinelibrary.controller;
import com.onlinelibrary.dao.impl.NotificationDAOImpl; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/librarian/notifications") public class NotificationManagementServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{r.setAttribute("members",WebSupport.SERVICE.userDAO().findMembers(""));WebSupport.view(r,s,"notification-admin.jsp");}catch(Exception e){WebSupport.fail(r,s,e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException,ServletException{try{String member=r.getParameter("memberId");new NotificationDAOImpl().announce(member==null||member.isBlank()?null:Long.valueOf(member),r.getParameter("title"),r.getParameter("message"));s.sendRedirect(r.getContextPath()+"/librarian/notifications?message=Notification+sent");}catch(Exception e){WebSupport.fail(r,s,e);}}}
